package main

import (
	"fmt"
	"strings"
)



type Node[T any] struct {
	Value T
	next  *Node[T]
	prev  *Node[T]
	root  *Node[T]
}

func (n *Node[T]) Next() *Node[T] { return n.next }
func (n *Node[T]) Prev() *Node[T] { return n.prev }

type List[T any] struct {
	root *Node[T]
	size int
}

func NewList[T any]() *List[T] {
	root := &Node[T]{}
	root.next = root
	root.prev = root
	root.root = root
	return &List[T]{root: root}
}

func (l *List[T]) Insert(it *Node[T], value T) *Node[T] {
	n := &Node[T]{Value: value, root: l.root}
	n.prev = it.prev
	n.next = it
	it.prev.next = n
	it.prev = n
	l.size++
	return n
}

func (l *List[T]) PushBack(value T) {
	l.Insert(l.root, value)
}

func (l *List[T]) Front() *Node[T] {
	if l.size == 0 {
		return l.root
	}
	return l.root.next
}

func (l *List[T]) Back() *Node[T] {
	if l.size == 0 {
		return l.root
	}
	return l.root.prev
}

func (l *List[T]) End() *Node[T] {
	return l.root
}

func (l *List[T]) Erase(n *Node[T]) *Node[T] {
	if n == l.root {
		return l.root
	}
	n.prev.next = n.next
	n.next.prev = n.prev
	l.size--
	return n.next
}

func (l *List[T]) String() string {
	values := []string{}
	for n := l.root.next; n != l.root; n = n.next {
		values = append(values, fmt.Sprint(n.Value))
	}
	return "[" + strings.Join(values, ", ") + "]"
}


type Editor struct {
	lines  *List[*List[rune]]
	lineIt *Node[*List[rune]]
	charIt *Node[rune]
}

func NewEditor() *Editor {
	lines := NewList[*List[rune]]()
	first := NewList[rune]()
	lines.PushBack(first)

	return &Editor{
		lines:  lines,
		lineIt: lines.Front(),
		charIt: first.End(),
	}
}

func (e *Editor) InsertChar(c rune) {
	line := e.lineIt.Value
	e.charIt = line.Insert(e.charIt, c)
	e.charIt = e.charIt.Next()
}

func (e *Editor) MoveLeft() {
	line := e.lineIt.Value

	if e.charIt != line.Front() {
		e.charIt = e.charIt.Prev()
		return
	}

	if e.lineIt.Prev() != e.lines.End() {
		e.lineIt = e.lineIt.Prev()
		e.charIt = e.lineIt.Value.End()
	}
}

func (e *Editor) MoveRight() {
	line := e.lineIt.Value

	if e.charIt != line.End() {
		e.charIt = e.charIt.Next()
		return
	}

	if e.lineIt.Next() != e.lines.End() {
		e.lineIt = e.lineIt.Next()
		e.charIt = e.lineIt.Value.Front()
	}
}

func (e *Editor) getColumn() int {
	line := e.lineIt.Value
	i := 0
	for it := line.Front(); it != e.charIt && it != line.End(); it = it.Next() {
		i++
	}
	return i
}

func (e *Editor) getCharAtColumn(line *List[rune], col int) *Node[rune] {
	it := line.Front()
	i := 0
	for it != line.End() && i < col {
		it = it.Next()
		i++
	}
	return it
}

func (e *Editor) MoveUp() {
	if e.lineIt.Prev() == e.lines.End() {
		return
	}
	col := e.getColumn()
	e.lineIt = e.lineIt.Prev()
	e.charIt = e.getCharAtColumn(e.lineIt.Value, col)
}

func (e *Editor) MoveDown() {
	if e.lineIt.Next() == e.lines.End() {
		return
	}
	col := e.getColumn()
	e.lineIt = e.lineIt.Next()
	e.charIt = e.getCharAtColumn(e.lineIt.Value, col)
}

func (e *Editor) Backspace() {
	line := e.lineIt.Value

	if e.charIt != line.Front() {
		e.charIt = line.Erase(e.charIt.Prev())
		return
	}

	if e.lineIt.Prev() != e.lines.End() {
		prevNode := e.lineIt.Prev()
		prevLine := prevNode.Value

		pos := prevLine.End()

		for it := line.Front(); it != line.End(); {
			next := it.Next()
			prevLine.Insert(prevLine.End(), it.Value)
			it = next
		}

		e.lines.Erase(e.lineIt)
		e.lineIt = prevNode
		e.charIt = pos
	}
}

func (e *Editor) Delete() {
	line := e.lineIt.Value

	if e.charIt != line.End() {
		e.charIt = line.Erase(e.charIt)
		return
	}

	if e.lineIt.Next() != e.lines.End() {
		nextNode := e.lineIt.Next()
		nextLine := nextNode.Value

		for it := nextLine.Front(); it != nextLine.End(); {
			next := it.Next()
			line.Insert(line.End(), it.Value)
			it = next
		}

		e.lines.Erase(nextNode)
	}
}

func (e *Editor) Enter() {
	line := e.lineIt.Value
	newLine := NewList[rune]()

	for it := e.charIt; it != line.End(); {
		next := it.Next()
		newLine.Insert(newLine.End(), it.Value)
		line.Erase(it)
		it = next
	}

	newNode := e.lines.Insert(e.lineIt.Next(), newLine)
	e.lineIt = newNode
	e.charIt = newLine.Front()
}

func (e *Editor) String() string {
	result := ""
	for l := e.lines.Front(); l != e.lines.End(); l = l.Next() {
		line := l.Value
		for c := line.Front(); c != line.End(); c = c.Next() {
			result += string(c.Value)
		}
		result += "\n"
	}
	return result
}



func main() {

	ed := NewEditor()

	for _, c := range "oi" {
		ed.InsertChar(c)
	}

	ed.Enter()

	for _, c := range "quixada" {
		ed.InsertChar(c)
	}

	ed.MoveUp()
	ed.MoveLeft()
	ed.Backspace()

	fmt.Println(ed.String())
}
